/** 
 * @file 01-authenticate.js
 * @description Validates JWT authentication token generation and stores it in the environment.
 */

// 1. Protocol & SLA Validations
pm.test("[AUTH-01] Status code is 200 OK", function () {
    pm.response.to.have.status(200);
    pm.response.to.be.json;
});

pm.test("[AUTH-02] Response time within SLA (< 1500ms)", function () {
    pm.expect(pm.response.responseTime).to.be.below(1500);
});

// 2. State Extraction & Persistence
try {
    const responseData = pm.response.json();

    pm.test("[AUTH-03] Response payload contains a valid token string", function () {
        pm.expect(responseData).to.have.property("token");
        pm.expect(responseData.token).to.be.a("string").that.is.not.empty;
    });

    if (responseData.token) {
        pm.environment.set("token", responseData.token);
        console.log(`[AUTH SUCCESS] Token stored successfully: ${responseData.token.substring(0, 6)}...`);
    }
} catch (error) {
    console.error("[AUTH ERROR] Failed to parse authentication JSON:", error);
}

/**
 * @file 02-create-booking.js
 * @description Validates booking creation, AJV JSON Schema contract, and stores the bookingId.
 */

const bookingContractSchema = {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "required": ["bookingid", "booking"],
    "properties": {
        "bookingid": { "type": "integer", "minimum": 1 },
        "booking": {
            "type": "object",
            "required": ["firstname", "lastname", "totalprice", "depositpaid", "bookingdates"],
            "properties": {
                "firstname": { "type": "string", "minLength": 1 },
                "lastname": { "type": "string", "minLength": 1 },
                "totalprice": { "type": "number", "minimum": 0 },
                "depositpaid": { "type": "boolean" },
                "bookingdates": {
                    "type": "object",
                    "required": ["checkin", "checkout"],
                    "properties": {
                        "checkin": { "type": "string" },
                        "checkout": { "type": "string" }
                    }
                },
                "additionalneeds": { "type": "string" }
            }
        }
    }
};

// 1. Protocol & Header Validations
pm.test("[BOOKING-CREATE-01] Status code is 200 OK", function () {
    pm.response.to.have.status(200);
    pm.expect(pm.response.headers.get("Content-Type")).to.include("application/json");
});

pm.test("[BOOKING-CREATE-02] Response time within SLA (< 1500ms)", function () {
    pm.expect(pm.response.responseTime).to.be.below(1500);
});

// 2. Contract Testing
pm.test("[BOOKING-CREATE-03] Response matches JSON Schema contract", function () {
    pm.response.to.have.jsonSchema(bookingContractSchema);
});

// 3. Business Logic Validations
try {
    const responseData = pm.response.json();

    pm.test("[BOOKING-CREATE-04] Booking ID generated as a positive integer", function () {
        pm.expect(responseData.bookingid).to.be.a("number").and.above(0);
        pm.environment.set("bookingId", responseData.bookingid);
        console.log(`[BOOKING CREATED] Generated ID: ${responseData.bookingid}`);
    });

    pm.test("[BOOKING-CREATE-05] Attributes match requested payload", function () {
        const booking = responseData.booking;

        pm.expect(booking.firstname).to.eql("John");
        pm.expect(booking.lastname).to.eql("Doe");
        pm.expect(booking.totalprice).to.eql(250);
        pm.expect(booking.depositpaid).to.be.true;
    })
} catch (error) {
    console.error("[BOOKING CREATE ERROR] Failed to parse JSON payload: ", error);
}

/**
 * @file 03-get-booking.js
 * @description Validates record retrieval integrity using the stored bookingId.
 */

pm.test("[BOOKING-GET-01] Status code is 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("[BOOKING-GET-02] Response time within SLA (< 1000ms)", function () {
    pm.expect(pm.response.responseTime).to.be.below(1000);
});

try {
    const responseData = pm.response.json();
    const currentBookingId = pm.environment.get("bookingId");

    pm.test(`[BOOKING-GET-03] Record details for ID ${currentBookingId} are complete`, function () {
        pm.expect(responseData.firstname).to.be.a("string").and.not.empty;
        pm.expect(responseData.lastname).to.be.a("string").and.not.empty;
        pm.expect(responseData.totalprice).to.be.a("number");
        pm.expect(responseData.bookingdates).to.have.all.keys("checkin", "checkout");
    });
} catch (error) {
    console.error("[BOOKING GET ERROR] Failed to process payload: ", error);
}

/**
 * @file 04-update-booking.js
 * @description Validates full resource updates (PUT) authorized via session cookie.
 */

pm.test("[BOOKING-UPDATE-01] Status code is 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("[BOOKING-UPDATE-02] Response time within SLA (<1500ms)", function () {
    pm.expect(pm.response.responseTime).to.be.below(1500);
});

try {
    const responseData = pm.response.json();

    pm.test("[BOOKING-UPDATE-03] Total price, dates and aditional needs updated successfully", function () {
        pm.expect(responseData.totalprice).to.eql(300);
        pm.expect(responseData.additionalneeds).to.eql("Late Checkout");
        pm.expect(responseData.bookingdates.checkout).to.eql("2026-10-12");
    });

} catch (error) {
    console.error("[BOOKING UPDATE ERROR] Failed to interpret response: ", error);
}

/**
 * @file 05-delete-booking.js
 * @description Validates resource removal and performs environment state cleanup.
 */

pm.test("[BOOKING-DELETE-01] Status code is 201 Created (Restful-Booker spec)", function () {
    pm.response.to.have.status(201);
});

pm.test("[BOOKING-DELETE-02] Confirmation string present in response body", function () {
    pm.expect(pm.response.text()).to.include("Created");
});

pm.environment.unset("bookingId");
console.log("[CLEANUP] Removed temporary 'bookingId' variable from environment.");
